-- Rate-limit counters shared by every api replica (WP-03; 02-database 7.6.15 and R-16). Generated by drizzle-kit,
-- then made UNLOGGED by hand (drizzle-kit cannot express it): a crash empties them, which only resets the windows.
CREATE UNLOGGED TABLE "auth_rate_limit" (
	"id" text PRIMARY KEY NOT NULL,
	"key" text NOT NULL,
	"count" integer NOT NULL,
	"last_request" bigint NOT NULL,
	CONSTRAINT "auth_rate_limit_key_uq" UNIQUE("key")
) WITH (fillfactor = 60);
--> statement-breakpoint
CREATE UNLOGGED TABLE "rate_limits" (
	"key" varchar(255) PRIMARY KEY NOT NULL,
	"points" integer DEFAULT 0 NOT NULL,
	"expire" bigint
) WITH (fillfactor = 60, autovacuum_vacuum_scale_factor = 0.02, autovacuum_vacuum_threshold = 500);
